# PreToolUse hook: block edits to Godot-generated files (.godot/ cache, .cs.uid).
# Exit 2 blocks the call and shows stderr to Claude.
import json
import sys


def main():
    data = json.load(sys.stdin)
    tool_input = data.get('tool_input') or {}
    p = f"{tool_input.get('file_path', '')}{tool_input.get('notebook_path', '')}".replace('\\', '/').lower()
    if '/.godot/' in p or p.endswith('.cs.uid'):
        print('Blocked: generated by Godot (.godot/ cache or .cs.uid); let the editor regenerate it.', file=sys.stderr)
        return 2
    return 0


sys.exit(main())
